      if (a.edge) scene.holdEdge(a.edge);
      const done = a.edge ? () => scene.releaseEdge(a.edge!) : undefined;
      return new Ink(host.layer(), [a.from, a.to], a.color ?? CYAN, a.durS ?? 1, host.px(), a.reverse ?? false, done);
