  {
    name: 'spark', tier: 'narrative', weight: 0.5, value: 3, cuttable: true, clock: 'accent', reduced: 'skip',
    make(host: FxHost, a: SparkArgs): Fx {
      return new Spark(host.layer(), a.from, a.to, a.color ?? CYAN, a.durS ?? 0.9, host.px(), a.size ?? 12);
