    if (!def || def.moves) return;
    const meta = { name: def.name, weight: def.weight, cuttable: def.cuttable, clock: def.clock };
    this.idleRunner.at((c.delayMs ?? 0) / 1000, () => {
      if (!this.host.scene() || motion.reduced) return;
      try {
