    : r)),
  estimateMs: { 'Comet Pod': 14090, 'Nova Pod': 48240, 'Quasar Pod': 250740, 'Pulsar Pod': 144980, 'Convoy Planning Pod': 17020, 'Harbor Pod': 29930 },
}, {
  id: 'E5a',
